int ext4_orphan_add(handle_t *handle, struct inode *inode) {
    int ret = 0;
    struct super_block *sb = inode->i_sb;
    struct ext4_super_block *es = EXT4_SB(sb)->s_es;
    struct ext4_inode_info *ei = EXT4_I(inode);

    if (!ext4_orphan_list_needed(sb, ei)) {
        return 0;
    }

    mutex_lock(&EXT4_SB(sb)->s_orphan_lock);

    if (ei->i_dtime) {
        ret = -EINVAL;
        goto out;
    }

    if (S_ISREG(inode->i_mode) || S_ISDIR(inode->i_mode) || S_ISLNK(inode->i_mode)) {
        ret = ext4_journal_get_write_access(handle, inode->i_ino);
        if (ret < 0) {
            goto out;
        }

        ret = ext4_journal_space_reserved(handle, sb, 1);
        if (ret < 0) {
            goto out;
        }

        if (le32_to_cpu(es->s_last_orphan) == 0) {
            es->s_last_orphan = cpu_to_le32(inode->i_ino);
            ext4_handle_dirty_metadata(handle, sb, es);
        }

        ei->i_orphan = 1;
        mark_inode_dirty(inode);

        list_add_tail(&ei->i_orphan_list, &EXT4_SB(sb)->s_orphan);
    } else {
        ret = -EINVAL;
    }

out:
    mutex_unlock(&EXT4_SB(sb)->s_orphan_lock);
    return ret;
}
